// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests proving event triggers fire on edges only
// Flo: arm states > feed ticks and temp files > assert verdicts, errors
// I/O: Schedules + temp dir files + fake clock > pass or fail
// ===================================================================
const std = @import("std"); const even = @import("ev-task-even.zig");
const tszz = std.testing; const statArmz = even.statArmz; const ArmzErro = even.ArmzErro; const Kind = even.Kind; const typeEvenChec = even.typeEvenChec;
fn iozzMake() std.Io.Threaded { return std.Io.Threaded.init(tszz.allocator, .{}); }
fn tmpzPath(tmpz: *std.testing.TmpDir) ![]const u8 { return std.fmt.allocPrint(tszz.allocator, ".zig-cache{c}tmp{c}{s}", .{ std.fs.path.sep, std.fs.path.sep, tmpz.sub_path }); }
test "armState accepts each control type" { const stat_boot = try statArmz("boot", null, null); try tszz.expectEqual(Kind.boot, stat_boot.kind); const stat_hand = try statArmz("hand", null, null); try tszz.expectEqual(Kind.hand, stat_hand.kind); const stat_even = try statArmz("even", "E:\\x", null); try tszz.expectEqualStrings("E:\\x", stat_even.path); const stat_queu = try statArmz("queu", "E:\\q", null); try tszz.expectEqual(Kind.queu, stat_queu.kind); const stat_flag = try statArmz("flag", "file:E:\\go.txt", null); try tszz.expectEqualStrings("E:\\go.txt", stat_flag.path); }
test "flag REQUIRES the file: prefix" { try tszz.expectError(ArmzErro.BadFlagPrefix, statArmz("flag", "E:\\go.txt", null)); try tszz.expectError(ArmzErro.NeedsPath, statArmz("flag", "file:", null)); }
test "path-needing types reject a missing or blank schedule" { for ([_][]const u8{ "even", "flag", "queu" }) |kind| { try tszz.expectError(ArmzErro.NeedsPath, statArmz(kind, null, null)); try tszz.expectError(ArmzErro.NeedsPath, statArmz(kind, "   ", null)); } }
test "boot fires once, immediately, when there is no delay" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var stat = try statArmz("boot", null, null); try tszz.expect(stat.duez(iozz, 1000)); try tszz.expect(!stat.duez(iozz, 2000)); try tszz.expect(!stat.duez(iozz, 999999)); }
test "boot honors dela before firing" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var stat = try statArmz("boot", null, 2); try tszz.expect(!stat.duez(iozz, 0)); try tszz.expect(!stat.duez(iozz, 60_000)); try tszz.expect(!stat.duez(iozz, 119_999)); try tszz.expect(stat.duez(iozz, 120_000)); try tszz.expect(!stat.duez(iozz, 180_000)); }
test "hand never fires on its own, only on request" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var stat = try statArmz("hand", null, null); var iter: u32 = 0; while (iter < 100) : (iter += 1) try tszz.expect(!stat.duez(iozz, @intCast(iter * 1000))); stat.hand_requ = true; try tszz.expect(stat.duez(iozz, 0)); try tszz.expect(!stat.duez(iozz, 0)); }
test "flag: a PRE-EXISTING file does not fire — baseline first" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var tmpz = tszz.tmpDir(.{}); defer tmpz.cleanup(); const dirz_path = try tmpzPath(&tmpz); defer tszz.allocator.free(dirz_path); try tmpz.dir.writeFile(iozz, .{ .sub_path = "go.txt", .data = "x" }); const sche = try std.fmt.allocPrint(tszz.allocator, "file:{s}{c}go.txt", .{ dirz_path, std.fs.path.sep }); defer tszz.allocator.free(sche); var stat = try statArmz("flag", sche, null); try tszz.expect(!stat.duez(iozz, 0)); try tszz.expect(!stat.duez(iozz, 1000)); }
test "flag: absent -> present is a rising edge that fires exactly once" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var tmpz = tszz.tmpDir(.{}); defer tmpz.cleanup(); const dirz_path = try tmpzPath(&tmpz); defer tszz.allocator.free(dirz_path); const sche = try std.fmt.allocPrint(tszz.allocator, "file:{s}{c}go.txt", .{ dirz_path, std.fs.path.sep }); defer tszz.allocator.free(sche); var stat = try statArmz("flag", sche, null); try tszz.expect(!stat.duez(iozz, 0)); try tmpz.dir.writeFile(iozz, .{ .sub_path = "go.txt", .data = "x" }); try tszz.expect(stat.duez(iozz, 1000)); try tszz.expect(!stat.duez(iozz, 2000)); try tmpz.dir.deleteFile(iozz, "go.txt"); try tszz.expect(!stat.duez(iozz, 3000)); try tmpz.dir.writeFile(iozz, .{ .sub_path = "go.txt", .data = "y" }); try tszz.expect(stat.duez(iozz, 4000)); }
test "even: mtime change fires, unchanged does not" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var tmpz = tszz.tmpDir(.{}); defer tmpz.cleanup(); const dirz_path = try tmpzPath(&tmpz); defer tszz.allocator.free(dirz_path); try tmpz.dir.writeFile(iozz, .{ .sub_path = "src.txt", .data = "one" }); const file_path = try std.fs.path.join(tszz.allocator, &.{ dirz_path, "src.txt" }); defer tszz.allocator.free(file_path); var stat = try statArmz("even", file_path, null); try tszz.expect(!stat.duez(iozz, 0)); try tszz.expect(!stat.duez(iozz, 1000)); stat.mtim_last -= 5000; try tszz.expect(stat.duez(iozz, 2000)); try tszz.expect(!stat.duez(iozz, 3000)); }
test "even: a missing path never fires" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var stat = try statArmz("even", "E:\\definitely\\not\\here\\x.txt", null); var iter: u32 = 0; while (iter < 20) : (iter += 1) try tszz.expect(!stat.duez(iozz, @intCast(iter * 1000))); }
test "queu: empty dir does not fire; a file does, and is claimed" { var iozz_impl = iozzMake(); defer iozz_impl.deinit(); const iozz = iozz_impl.io(); var tmpz = tszz.tmpDir(.{}); defer tmpz.cleanup(); const dirz_path = try tmpzPath(&tmpz); defer tszz.allocator.free(dirz_path); var stat = try statArmz("queu", dirz_path, null); try tszz.expect(!stat.duez(iozz, 0)); try tmpz.dir.writeFile(iozz, .{ .sub_path = "job1.txt", .data = "work" }); try tszz.expect(stat.duez(iozz, 1000)); try tszz.expectEqualStrings("job1.txt", stat.clai()); try tszz.expect(stat.duez(iozz, 2000)); try tmpz.dir.deleteFile(iozz, "job1.txt"); try tszz.expect(!stat.duez(iozz, 3000)); }
test "isEventType covers exactly the 5 S3 types" { for ([_][]const u8{ "boot", "even", "flag", "hand", "queu" }) |item| try tszz.expect(typeEvenChec(item)); for ([_][]const u8{ "cron", "puls", "once", "sola", "loop", "tcpr" }) |item| try tszz.expect(!typeEvenChec(item)); }
